import{_ as a,c as i,o as l,ag as t}from"./chunks/framework.C86mscM5.js";const p=JSON.parse('{"title":"CI/CD","description":"","frontmatter":{},"headers":[],"relativePath":"devops/ci-cd/index.md","filePath":"devops/ci-cd/index.md","lastUpdated":1788689791000}'),o={name:"devops/ci-cd/index.md"};function r(n,e,d,c,s,h){return l(),i("div",null,e[0]||(e[0]=[t('<h1 id="ci-cd" tabindex="-1">CI/CD <a class="header-anchor" href="#ci-cd" aria-label="Permalink to &quot;CI/CD&quot;">​</a></h1><p>CI/CD 将代码验证、制品构建和环境部署组成可追溯的自动化流水线。</p><h2 id="ci、delivery、deployment" tabindex="-1">CI、Delivery、Deployment <a class="header-anchor" href="#ci、delivery、deployment" aria-label="Permalink to &quot;CI、Delivery、Deployment&quot;">​</a></h2><ul><li><strong>Continuous Integration</strong>：频繁合并代码，并快速执行静态检查、测试和构建。</li><li><strong>Continuous Delivery</strong>：主干始终处于可发布状态，生产部署可以包含人工审批。</li><li><strong>Continuous Deployment</strong>：通过全部门禁的变更自动部署到生产。</li></ul><h2 id="流水线设计" tabindex="-1">流水线设计 <a class="header-anchor" href="#流水线设计" aria-label="Permalink to &quot;流水线设计&quot;">​</a></h2><p><code>触发 → 安装依赖 → Lint/测试 → 构建 → SBOM/扫描 → 发布制品 → 部署 → 冒烟测试 → 观测/回滚</code></p><p>各 Job 应声明输入、输出、权限、超时和重试边界。缓存用于提速，Artifact 用于在 Job 或环境之间传递不可变结果，两者不能混用。</p><h3 id="触发与并发" tabindex="-1">触发与并发 <a class="header-anchor" href="#触发与并发" aria-label="Permalink to &quot;触发与并发&quot;">​</a></h3><ul><li>Pull Request 流水线执行快速检查，不使用生产 Secret。</li><li>主干流水线生成可发布制品；Tag 或审批触发正式发布。</li><li>为同一分支设置并发组，取消已被新提交取代的旧任务。</li><li>定时任务用于依赖扫描、证书检查等非提交触发工作。</li></ul><h3 id="job-边界" tabindex="-1">Job 边界 <a class="header-anchor" href="#job-边界" aria-label="Permalink to &quot;Job 边界&quot;">​</a></h3><ul><li>将 Lint、单元测试、构建和安全扫描拆成可并行且可独立重试的 Job。</li><li>固定运行器、包管理器和运行时版本；校验锁文件。</li><li>缓存 Key 应包含锁文件摘要，缓存未命中不能影响正确性。</li><li>制品包含版本与校验和，并设置合理保留期。</li></ul><h3 id="门禁与部署" tabindex="-1">门禁与部署 <a class="header-anchor" href="#门禁与部署" aria-label="Permalink to &quot;门禁与部署&quot;">​</a></h3><ul><li>保护生产环境，限制可审批者和可用 Secret。</li><li>部署前验证制品签名、扫描结果和来源。</li><li>部署任务只负责部署既有制品，不再次编译。</li><li>部署后执行健康检查和烟雾测试，失败时停止推广并按策略回滚。</li></ul><h3 id="安全默认值" tabindex="-1">安全默认值 <a class="header-anchor" href="#安全默认值" aria-label="Permalink to &quot;安全默认值&quot;">​</a></h3><ul><li>Job 权限默认只读，按需授予上传制品或部署权限。</li><li>优先使用 OIDC 短期凭据，避免长期云密钥。</li><li>第三方 Action、镜像和模板固定到可信版本或摘要。</li><li>对 Fork PR 和不受信任输入禁用高权限任务。</li></ul><h3 id="失败处理" tabindex="-1">失败处理 <a class="header-anchor" href="#失败处理" aria-label="Permalink to &quot;失败处理&quot;">​</a></h3><p>区分可重试的网络故障、确定性的测试失败和部署后的生产故障。不要用无限重试掩盖不稳定测试；生产失败需要保留部署、日志、指标和制品证据。</p>',17)]))}const b=a(o,[["render",r]]);export{p as __pageData,b as default};
